sys_script_include.script:
var GeminiUtils = Class.create();
GeminiUtils.prototype = {
    initialize: function() {
        var protocol = 'https://';
        var domain = 'generativelanguage.' + 'googleapis.com';
        var version = '/v1beta/models/';
        var model = 'gemini-3.5-flash:generateContent';

        this.endpoint = protocol + domain + version + model;
        this.apiKey = gs.getProperty('x_2311790_skills_0.gemini_api_key');
    },

    parseResumeAttachment: function(tableName, recordSysId) {
        try {
            if (!this.apiKey) {
                gs.error('GeminiUtils: Missing x_2311790_skills_0.gemini_api_key property.');
                return null;
            }

            // 1. Find the most recent PDF attachment on this record
            var attGr = new GlideRecord('sys_attachment');
            attGr.addQuery('table_name', tableName);
            attGr.addQuery('table_sys_id', recordSysId);
            attGr.addQuery('content_type', 'application/pdf');
            attGr.orderByDesc('sys_created_on');
            attGr.setLimit(1);
            attGr.query();

            if (!attGr.next()) {
                gs.warn('GeminiUtils: No PDF attachment found for ' + tableName + ' (' + recordSysId + ')');
                return null;
            }

            // 2. Read the PDF attachment as Base64
            var gsa = new GlideSysAttachment();
            var pdfBase64 = gsa.getContentBase64(attGr);

            if (!pdfBase64) {
                gs.error('GeminiUtils: Failed to encode PDF attachment to Base64.');
                return null;
            }

            // 3. Build your structured JSON payload
            var payload = {
                "systemInstruction": {
                    "parts": [{
                        "text": "You are an accurate resume parser. Extract only facts explicitly present in the attached PDF resume. Do not invent skills, roles, or experience."
                    }]
                },
                "contents": [{
                    "role": "user",
                    "parts": [
                        {
                            "inlineData": {
                                "mimeType": "application/pdf",
                                "data": pdfBase64
                            }
                        },
                        {
                            "text": "Extract a short professional headline and a factual parsed_resume summary (including key skills and experience) from this PDF."
                        }
                    ]
                }],
                "generationConfig": {
                    "temperature": 0.1,
                    "responseMimeType": "application/json",
                    "responseSchema": {
                        "type": "OBJECT",
                        "properties": {
                            "headline": {
                                "type": "STRING",
                                "description": "Short professional headline, e.g. '3rd Year CS Student | Backend Developer'"
                            },
                            "parsed_resume": {
                                "type": "STRING",
                                "description": "Concise, factual summary of the candidate's background, experience, and technical skills."
                            }
                        },
                        "required": ["headline", "parsed_resume"],
                        "propertyOrdering": ["headline", "parsed_resume"]
                    }
                }
            };

            // 4. Execute the HTTP POST directly without a REST Message record
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this.endpoint);
            r.setHttpMethod('POST');
            r.setRequestHeader('Content-Type', 'application/json');
            r.setRequestHeader('x-goog-api-key', this.apiKey);
            r.setRequestBody(JSON.stringify(payload));

            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();

            if (status == 200) {
                var parsedResponse = JSON.parse(body);
                var firstCandidate = parsedResponse.candidates.shift();
                var firstPart = firstCandidate.content.parts.shift();

                // Returns a JS object: { headline: "...", parsed_resume: "..." }
                return JSON.parse(firstPart.text);
            } else {
                gs.error('GeminiUtils API Error (' + status + '): ' + body);
                return null;
            }
        } catch (ex) {
            gs.error('GeminiUtils Exception: ' + ex.message);
            return null;
        }
    },

    type: 'GeminiUtils'
};
